code_sketch:
type Expr =
  | { kind: 'num'; value: number }
  | { kind: 'add'; left: Expr; right: Expr };
function evaluate(e: Expr, ctx: Ctx): number {
  switch (e.kind) {
    case 'num': return e.value;
    case 'add': return evaluate(e.left, ctx) + evaluate(e.right, ctx);
    default: { const unhandled: never = e; throw new Error(`unhandled ${String(unhandled)}`); }
  }
}

