interface IExpression { interpret(ctx: Context): number }
class Numeral implements IExpression {
  constructor(private readonly value: number) {}
  interpret(_ctx: Context): number { return this.value }
}
class Add implements IExpression {
  constructor(private readonly left: IExpression, private readonly right: IExpression) {}
  interpret(ctx: Context): number {
    return this.left.interpret(ctx) + this.right.interpret(ctx)
  }
}
